 ('XD02', UR, 'Upload setting part massal', 'User Procurement upload file Excel (sheet "Upload") untuk Add (upload = A) dan Edit (upload = E) part.', '', ''),
 ('XD02', VAL, 'Cek file', '.xlsx, ≤ 5 MB, sheet "Upload" ada, 1–5.000 baris, header 7 kolom template (kolom tambahan diabaikan).', '', ''),
 ('XD02', VAL, 'Cek baris', 'upload = A atau E; part ada di master; A belum terdaftar / E sudah terdaftar; tidak duplikat di file; min_mad bulat ≥ 0, pcs_case & max_case_day bulat > 0; status sesuai aturan (A kosong, E tidak boleh menjadi Candidate); Effective Start Date wajib selama Candidate dan ≥ hari ini; Max Case/Day ≥ total mapping.', '', 'TB_M_PART_MASTER, TB_M_PART_CANDIDATE, TB_M_PART_CANDIDATE_DEST'),
 ('XD02', BL, 'All-or-nothing', 'Semua error dikumpulkan (user perbaiki sekali); 1 error = seluruh file ditolak, tidak ada yang disimpan.', '', ''),
 ('XD02', BL, 'Simpan', 'upload A insert status Candidate; upload E update kolom yang berubah (baris tanpa perubahan di-skip). Part tersimpan → SYNC_STATUS 0, LAST_SOURCE UPLOAD, history.', '', 'TB_M_PART_CANDIDATE, TB_H_PART_CANDIDATE'),
 ('XD02', MSG, 'Result report', 'Hasil COMPLETED / REJECTED di Log; result report berisi error per baris + sheet Re-upload.', '', 'Upload Log'),
