 # XD05
 ('XD05', UR, 'Status part otomatis', 'Part crossdock ditentukan Active / Inactive dari demand historis, bukan manual.', '', ''),
 ('XD05', BL, 'Proses 1 – rata-rata MAD', 'Ambil demand range bulan historis sebelum bulan berjalan (jumlah bulan di system master, mis. 6). Semua part terdaftar yang Effective Start Date-nya sudah tiba. Rata-rata = total MAD ÷ jumlah bulan master (pembagi tetap, bulan tanpa data = 0), 2 desimal.', 'Part 52119BZV60, 202604–202609: Min MAD 500 → Active, 600 → Inactive.', 'TB_R_ACTUAL_DEMAND_SUMMARY, TB_R_PART_DAD_RESULT'),
 ('XD05', BL, 'Proses 1 – status', 'Rata-rata ≥ Min MAD → Active; < Min MAD → Inactive. Batch boleh menimpa status manual. Active → Inactive di-set No Sync (supaya dikirim flag N). Perubahan lain tidak membuat No Sync. History event CALC source BATCH.', '', 'TB_M_PART_CANDIDATE, TB_H_PART_CANDIDATE'),
 ('XD05', BL, 'Proses 2 – result MAD per destinasi', 'Part Active; order type N + S dijumlahkan; group per part + GROUPING_BUYER_CD + GROUPING_PD_CD (destination code 7 digit, mis. 9722D + 10 = 9722D10); harus ada di TB_M_H0125_DESTINATION (tidak ada → error).', '', 'TB_M_H0125_DESTINATION'),
 ('XD05', BL, 'Proses 2 – Case/Day', 'Urut result MAD terbesar; kalau destinasi > Max Case/Day hanya top N (N = Max Case/Day) dipakai. Case/Day = result MAD ÷ Σ result MAD terpakai × Max Case/Day; dibulatkan bilangan bulat, minimal 1 case per destinasi, total = Max Case/Day. Simpan sebagai periode baru (periode lama read only).', '', 'TB_M_PART_CANDIDATE_DEST'),
 ('XD05', BL, 'Kontrol batch', 'All-or-nothing per proses; proses 2 hanya jalan kalau proses 1 sukses. Auto retry 3x; trigger manual dari XD01; last success date per proses.', '', ''),
